#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 4271 §4.5 NOTIFICATION: error code 6 (Cease), subcode 2 (Administrative Shutdown), no data.
    fn vector() -> Vec<u8> {
        vec![0x06, 0x02]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::BgpNotification);
        let l = p.find_layer(ProtoId::BgpNotification).unwrap();
        assert_eq!(p.get(l, "error_code").unwrap(), FieldValue::Uint(6));
        assert_eq!(p.get(l, "error_subcode").unwrap(), FieldValue::Uint(2));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::BgpNotification);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::BgpNotification);
        let l = p.find_layer(ProtoId::BgpNotification).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::BgpNotification, false, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
